CREATE USER jamasp_ro WITH PASSWORD '…';
GRANT CONNECT ON DATABASE your_db TO jamasp_ro;
GRANT USAGE ON SCHEMA public TO jamasp_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO jamasp_ro;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO jamasp_ro;
ALTER USER jamasp_ro SET default_transaction_read_only = on;
